CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"4a08c28b-a62e-5df2-88b7-930f0d4dd30e","source_id":"0494","name_en":"incline reverse grip push-up","name_ar":"\u0627\u0646\u062d\u062f\u0631 \u062f\u0641\u0639 \u0645\u0627 \u064a\u0635\u0644 \u0642\u0628\u0636\u0629 \u0639\u0643\u0633\u064a\u0629","match_names":["incline reverse grip push-up"],"muscle":"chest","equipment":"bodyweight","aliases":["incline reverse grip push-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Place your hands on the edge of a bench or elevated surface, slightly wider than shoulder-width apart.\nExtend your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.\nLower your chest towards the bench by bending your elbows, keeping them close to your sides.\nPause for a moment at the bottom, then push yourself back up to the starting position by extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0645\u0642\u0639\u062f \u0623\u0648 \u0633\u0637\u062d \u0645\u0631\u062a\u0641\u0639\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u064a\u062f\u064a\u0643 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u062e\u0644\u0641\u0643\u060c \u0645\u0633\u062a\u0631\u064a\u062d\u064b\u0627 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643\u060c \u0644\u064a\u0634\u0643\u0644 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0643\u0639\u0628\u0643.\n\u0627\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0645\u0642\u0639\u062f \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643\u060c \u0648\u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0646\u0641\u0633\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0494","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0494-XaaRnRn.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0494-XaaRnRn.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b3cf0e5d-7945-526d-8692-fc87faa99aff","source_id":"3011","name_en":"incline scapula push up","name_ar":"\u0631\u0641\u0639 \u0644\u0648\u062d \u0627\u0644\u0643\u062a\u0641 \u0627\u0644\u0645\u0627\u0626\u0644 \u0644\u0623\u0639\u0644\u0649","match_names":["incline scapula push up"],"muscle":"serratus_anterior","equipment":"bodyweight","aliases":["incline scapula push up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Set up an incline bench at a 45-degree angle.\nPlace your hands on the bench slightly wider than shoulder-width apart.\nPosition your feet on the ground, hip-width apart.\nLower your chest towards the bench, keeping your elbows tucked in.\nAs you lower, retract your shoulder blades, squeezing your scapulae together.\nPush through your palms to extend your arms and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u0627\u064b \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0639\u0631\u0636 \u0645\u0641\u0635\u0644 \u0627\u0644\u0648\u0631\u0643.\n\u0627\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u0637\u0648\u064a\u064a\u0646 \u0644\u0644\u062f\u0627\u062e\u0644.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u0646\u0632\u0644\u060c \u0627\u0633\u062d\u0628 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0638\u0627\u0645 \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u0627\u062f\u0641\u0639 \u0628\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3011","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"serratus anterior","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3011-GdMa1ET.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3011-GdMa1ET.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8bdeb55e-a109-55e6-8fb7-6b126ea3a3a3","source_id":"0495","name_en":"incline twisting sit-up","name_ar":"\u0627\u0646\u062d\u062f\u0631 \u0627\u0644\u062a\u0648\u0627\u0621 \u0627\u0644\u0627\u0639\u062a\u0635\u0627\u0645","match_names":["incline twisting sit-up"],"muscle":"core","equipment":"bodyweight","aliases":["incline twisting sit-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Set up an incline bench at a 45-degree angle.\nLie down on the bench with your feet secured under the foot pads.\nPlace your hands behind your head or across your chest.\nEngage your abs and lift your upper body off the bench, curling forward.\nAs you curl up, twist your torso to one side, bringing your elbow towards the opposite knee.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat the movement, this time twisting your torso to the other side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0645\u0642\u0639\u062f \u0645\u0627\u0626\u0644 \u0628\u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0645\u0639 \u062a\u062b\u0628\u064a\u062a \u0642\u062f\u0645\u064a\u0643 \u062a\u062d\u062a \u0645\u0646\u0635\u0627\u062a \u0627\u0644\u0642\u062f\u0645.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0623\u0648 \u0639\u0628\u0631 \u0635\u062f\u0631\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0646 \u0627\u0644\u0645\u0642\u0639\u062f\u060c \u0645\u0639 \u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0623\u062b\u0646\u0627\u0621 \u062a\u062c\u0639\u064a\u062f\u0643\u060c \u0642\u0645 \u0628\u0644\u0641 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0648\u062c\u0644\u0628 \u0645\u0631\u0641\u0642\u0643 \u0646\u062d\u0648 \u0627\u0644\u0631\u0643\u0628\u0629 \u0627\u0644\u0645\u0642\u0627\u0628\u0644\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0629 \u0642\u0645 \u0628\u0644\u0641 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0495","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0495-9ZGZuOD.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0495-9ZGZuOD.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"c4b76223-0d97-5cfa-8d4c-7aad90374725","source_id":"1564","name_en":"intermediate hip flexor and quad stretch","name_ar":"\u062b\u0646\u064a\u0629 \u0627\u0644\u0648\u0631\u0643 \u0627\u0644\u0645\u062a\u0648\u0633\u0637\u0629 \u0648\u062a\u0645\u062a\u062f \u0631\u0628\u0627\u0639\u064a\u0629","match_names":["intermediate hip flexor and quad stretch"],"muscle":"quads","equipment":"rope","aliases":["intermediate hip flexor and quad stretch"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Stand upright with your feet shoulder-width apart.\nHold onto a stable object for support.\nBend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.\nSlowly pull your right foot towards your glutes, feeling a stretch in your right quad.\nHold the stretch for 20-30 seconds.\nRelease the stretch and repeat on the left side.","steps_ar":"\u0642\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0644\u062a\u0645\u0633\u0643 \u0628\u062c\u0633\u0645 \u0645\u0633\u062a\u0642\u0631 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0627\u062f\u0641\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0646\u062d\u0648 \u0623\u0631\u062f\u0627\u0641\u0643\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u0628\u0644 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0633\u062d\u0628 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0628\u0637\u0621 \u0646\u062d\u0648 \u0623\u0631\u062f\u0627\u0641\u0643\u060c \u0648\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0631\u0628\u0627\u0639\u064a\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f \u0648\u0643\u0631\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u064a\u0633\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1564","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1564-tFGKm99.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1564-tFGKm99.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"88ab9120-07d8-5180-8848-6fec2ffccf88","source_id":"0496","name_en":"inverse leg curl (bench support)","name_ar":"\u062a\u062c\u0639\u064a\u062f \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0639\u0643\u0633\u064a (\u062f\u0639\u0645 \u0645\u0642\u0627\u0639\u062f \u0627\u0644\u0628\u062f\u0644\u0627\u0621)","match_names":["inverse leg curl (bench support)"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["inverse leg curl (bench support)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie face down on a bench with your hips at the edge and your legs extended straight behind you.\nHold onto the bench for support.\nKeeping your upper body still, bend your knees and curl your legs towards your glutes.\nPause for a moment at the top, then slowly extend your legs back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u0648\u0636\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0641\u0629 \u0648\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u062e\u0644\u0641\u0643 \u0645\u0628\u0627\u0634\u0631\u0629.\n\u0627\u0644\u062a\u0645\u0633\u0643 \u0628\u0627\u0644\u0645\u0642\u0639\u062f \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062b\u0628\u0627\u062a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643\u060c \u0648\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0644\u0641 \u0633\u0627\u0642\u064a\u0643 \u0646\u062d\u0648 \u0639\u0636\u0644\u0629 \u0627\u0644\u0645\u0624\u062e\u0631\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0496","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0496-ms7tjSG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0496-ms7tjSG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"a263e680-236f-5ba5-822c-3868d980f798","source_id":"2400","name_en":"inverse leg curl (on pull-up cable machine)","name_ar":"\u062a\u062c\u0639\u064a\u062f \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0639\u0643\u0633\u064a (\u0639\u0644\u0649 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0627\u0644\u0642\u0627\u0628\u0644 \u0644\u0644\u0633\u062d\u0628)","match_names":["inverse leg curl (on pull-up cable machine)"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["inverse leg curl (on pull-up cable machine)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Adjust the cable machine so that the ankle straps are at the lowest setting.\nLie face down on the bench with your legs extended and the ankle straps attached to your feet.\nHold onto the handles of the bench for stability.\nBend your knees and curl your legs towards your glutes, squeezing your hamstrings.\nPause for a moment at the top of the movement, then slowly lower your legs back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0623\u062d\u0632\u0645\u0629 \u0627\u0644\u0643\u0627\u062d\u0644 \u0641\u064a \u0623\u062f\u0646\u0649 \u0645\u0633\u062a\u0648\u0649.\n\u0627\u0633\u062a\u0644\u0642\u0650 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0648\u062c\u0647\u0643 \u0644\u0644\u0623\u0633\u0641\u0644 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0631\u0628\u0637 \u0623\u0634\u0631\u0637\u0629 \u0627\u0644\u0643\u0627\u062d\u0644 \u0628\u0642\u062f\u0645\u064a\u0643.\n\u0627\u0644\u062a\u0645\u0633\u0643 \u0628\u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u0627\u0633\u062a\u0642\u0631\u0627\u0631.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0644\u0641 \u0633\u0627\u0642\u064a\u0643 \u0646\u062d\u0648 \u0623\u0631\u062f\u0627\u0641\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2400","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2400-0rHfvy9.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2400-0rHfvy9.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5349be79-9792-5573-85ca-01f96811448d","source_id":"0499","name_en":"inverted row","name_ar":"\u0635\u0641 \u0645\u0642\u0644\u0648\u0628","match_names":["inverted row"],"muscle":"back","equipment":"bodyweight","aliases":["inverted row"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Set up a bar at waist height or use a suspension trainer.\nStand facing the bar or suspension trainer, with your feet shoulder-width apart.\nGrab the bar or handles with an overhand grip, slightly wider than shoulder-width apart.\nLean back, keeping your body straight and your heels on the ground.\nPull your chest towards the bar or handles, squeezing your shoulder blades together.\nPause for a moment at the top, then slowly lower yourself back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0634\u0631\u064a\u0637 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u062e\u0635\u0631 \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0645 \u0645\u062f\u0631\u0628 \u0627\u0644\u062a\u0639\u0644\u064a\u0642.\n\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0628\u0627\u0631 \u0623\u0648 \u0645\u062f\u0631\u0628 \u0627\u0644\u062a\u0639\u0644\u064a\u0642\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0628\u0627\u0644\u0642\u0636\u064a\u0628 \u0623\u0648 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0633\u062a\u0646\u062f \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u062c\u0633\u0645\u0643 \u0648\u0643\u0639\u0628\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0627\u0633\u062d\u0628 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0628\u0627\u0631 \u0623\u0648 \u0627\u0644\u0645\u0642\u0627\u0628\u0636\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0646\u0641\u0633\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0499","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0499-bZGHsAZ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0499-bZGHsAZ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"dc8be57f-32af-57ae-87f8-ec5e73aae8b1","source_id":"2300","name_en":"inverted row bent knees","name_ar":"\u0635\u0641 \u0645\u0642\u0644\u0648\u0628 \u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646","match_names":["inverted row bent knees"],"muscle":"back","equipment":"bodyweight","aliases":["inverted row bent knees"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Set up a bar at waist height and lie underneath it.\nGrab the bar with an overhand grip, slightly wider than shoulder-width apart.\nPosition your body so that your heels are on the ground and your body is straight.\nPull your chest up towards the bar by squeezing your shoulder blades together.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u0625\u0639\u062f\u0627\u062f \u0634\u0631\u064a\u0637 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u062e\u0635\u0631 \u0648\u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u062a\u062d\u062a\u0647.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0628\u0627\u0631 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0636\u0639 \u062c\u0633\u0645\u0643 \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0643\u0639\u0628\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0627\u064b.\n\u0627\u0633\u062d\u0628 \u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0627\u062a\u062c\u0627\u0647 \u0627\u0644\u0628\u0627\u0631 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u06