needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0498-jdiExfW.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0498-jdiExfW.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f4013f29-70e8-5f4c-8043-c82e648be144","source_id":"1419","name_en":"iron cross stretch","name_ar":"\u062a\u0645\u062a\u062f \u0639\u0628\u0631 \u0627\u0644\u062d\u062f\u064a\u062f","match_names":["iron cross stretch"],"muscle":"glutes","equipment":"bodyweight","aliases":["iron cross stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your arms extended out to the sides.\nRaise your legs up towards the ceiling, keeping them straight.\nSlowly lower your legs to one side, aiming to touch the floor with your feet.\nHold the stretch for a few seconds, then return your legs to the starting position.\nRepeat the stretch on the other side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0627\u0631\u0641\u0639\u064a \u0633\u0627\u0642\u064a\u0643 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0628\u0647\u062f\u0641 \u0644\u0645\u0633 \u0627\u0644\u0623\u0631\u0636 \u0628\u0642\u062f\u0645\u064a\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0623\u0639\u062f \u0633\u0627\u0642\u064a\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062a\u0645\u062f\u062f \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1419","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","quadriceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1419-pZwUsKB.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1419-pZwUsKB.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"6a67a5c6-44cd-52cd-835d-beed0797b27c","source_id":"1297","name_en":"isometric chest squeeze","name_ar":"\u0636\u063a\u0637 \u0645\u062a\u0633\u0627\u0648\u064a \u0627\u0644\u0642\u064a\u0627\u0633 \u0639\u0644\u0649 \u0627\u0644\u0635\u062f\u0631","match_names":["isometric chest squeeze"],"muscle":"chest","equipment":"bodyweight","aliases":["isometric chest squeeze"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your knees slightly bent.\nExtend your arms straight out in front of you, parallel to the ground, with your palms facing each other.\nSqueeze your chest muscles together as hard as you can, while keeping your arms straight.\nHold this position for a few seconds, focusing on contracting your chest muscles.\nRelease the squeeze and relax your chest muscles.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643\u060c \u0628\u0627\u0644\u062a\u0648\u0627\u0632\u064a \u0645\u0639 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0645\u0648\u0627\u062c\u0647\u0629 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643 \u0645\u0639\u064b\u0627 \u0628\u0623\u0642\u0635\u0649 \u0642\u0648\u0629 \u0645\u0645\u0643\u0646\u0629\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u0645\u0639 \u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0639\u0644\u0649 \u0627\u0646\u0642\u0628\u0627\u0636 \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643.\n\u062d\u0631\u0631 \u0627\u0644\u0636\u063a\u0637 \u0648\u0627\u0633\u062a\u0631\u062e\u064a \u0639\u0636\u0644\u0627\u062a \u0635\u062f\u0631\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1297","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1297-HbSG1Pw.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1297-HbSG1Pw.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"d02570ef-30fb-5129-8364-15837aa6e501","source_id":"0500","name_en":"isometric wipers","name_ar":"\u0645\u0633\u0627\u062d\u0627\u062a \u0645\u062a\u0633\u0627\u0648\u064a\u0629 \u0627\u0644\u0642\u064a\u0627\u0633","match_names":["isometric wipers"],"muscle":"chest","equipment":"bodyweight","aliases":["isometric wipers"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Start by lying flat on your back on a mat or bench.\nExtend your arms straight out to the sides, perpendicular to your body.\nEngage your core and lift both legs off the ground, keeping them together and straight.\nSlowly lower your legs to one side, aiming to touch the ground with your feet while maintaining control.\nPause for a moment, then use your core to lift your legs back to the starting position.\nRepeat the movement, this time lowering your legs to the opposite side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u062d\u0635\u064a\u0631\u0629 \u0623\u0648 \u0645\u0642\u0639\u062f.\n\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646\u060c \u0628\u0634\u0643\u0644 \u0639\u0645\u0648\u062f\u064a \u0639\u0644\u0649 \u062c\u0633\u0645\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u062c\u0630\u0639\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0645\u0627 \u0645\u0639\u064b\u0627 \u0648\u0645\u0633\u062a\u0642\u064a\u0645\u062a\u064a\u0646.\n\u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u062c\u0627\u0646\u0628 \u0648\u0627\u062d\u062f\u060c \u0628\u0647\u062f\u0641 \u0644\u0645\u0633 \u0627\u0644\u0623\u0631\u0636 \u0628\u0642\u062f\u0645\u064a\u0643 \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u0637\u0631\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u0633\u062a\u062e\u062f\u0645 \u062c\u0630\u0639\u0643 \u0644\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u0629 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0500","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0500-11wrviz.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0500-11wrviz.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8ccac998-1c4b-5ddc-8089-70d72b3814d1","source_id":"0501","name_en":"jack burpee","name_ar":"\u062c\u0627\u0643 \u0628\u064a\u0631\u0628\u064a","match_names":["jack burpee"],"muscle":"cardio","equipment":"bodyweight","aliases":["jack burpee"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Start in a standing position with your feet shoulder-width apart.\nLower your body into a squat position, placing your hands on the ground in front of you.\nKick your feet back, landing in a push-up position.\nPerform a push-up, lowering your chest to the ground and then pushing back up.\nJump your feet forward, landing in a squat position.\nJump up explosively, reaching your arms overhead.\nLand softly and immediately lower back into the squat position to begin the next repetition.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643.\n\u0627\u0631\u0643\u0644 \u0642\u062f\u0645\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641\u060c \u0648\u0627\u0647\u0628\u0637 \u0641\u064a \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0636\u063a\u0637.\n\u0642\u0645 \u0628\u0625\u062c\u0631\u0627\u0621 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637\u060c \u0645\u0639 \u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u062b\u0645 \u0627\u0644\u062f\u0641\u0639 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0642\u0641\u0632 \u0628\u0642\u062f\u0645\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0648\u0647\u0628\u0637 \u0641\u064a \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u0627\u0642\u0641\u0632 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0644\u062a\u0635\u0644 \u0625\u0644\u0649 \u0630\u0631\u0627\u0639\u064a\u0643 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0627\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u062b\u0645 \u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0644\