neyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0507-mbkgB44.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"62176c5f-c48b-5251-86dd-f3b7800e177b","source_id":"0508","name_en":"janda sit-up","name_ar":"\u062c\u0627\u0646\u062f\u0627 \u0627\u0644\u0627\u0639\u062a\u0635\u0627\u0645","match_names":["janda sit-up"],"muscle":"core","equipment":"bodyweight","aliases":["janda sit-up"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your knees bent and feet flat on the ground.\nPlace your hands behind your head with your elbows pointing outwards.\nEngaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.\nPause for a moment at the top, then slowly lower your upper body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u062e\u0627\u0631\u062c.\n\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643\u060c \u0627\u0631\u0641\u0639 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u062b\u0645 \u0627\u0646\u062d\u0646\u064a \u0644\u0644\u0623\u0645\u0627\u0645 \u062d\u062a\u0649 \u064a\u0635\u0644 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0632\u0627\u0648\u064a\u0629 45 \u062f\u0631\u062c\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0627\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0508","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0508-1GPHRyK.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0508-1GPHRyK.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b9631aae-a081-587c-8cf9-897024b9758c","source_id":"2612","name_en":"jump rope","name_ar":"\u0627\u0644\u0642\u0641\u0632 \u0639\u0644\u0649 \u0627\u0644\u062d\u0628\u0644","match_names":["jump rope"],"muscle":"cardio","equipment":"rope","aliases":["jump rope"],"logging_mode":"timed","load_convention":"external_total","guidance":{"steps_en":"Hold the handles of the jump rope with your hands, palms facing inward.\nStand with your feet shoulder-width apart and knees slightly bent.\nSwing the rope over your head and jump over it as it comes towards your feet.\nLand softly on the balls of your feet and repeat the jump as the rope comes around again.\nContinue jumping for the desired duration or number of repetitions.","steps_ar":"\u0623\u0645\u0633\u0643 \u0645\u0642\u0627\u0628\u0636 \u062d\u0628\u0644 \u0627\u0644\u0642\u0641\u0632 \u0628\u064a\u062f\u064a\u0643\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u062f\u0627\u062e\u0644.\n\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0631\u062c\u062d\u0629 \u0627\u0644\u062d\u0628\u0644 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643 \u0648\u0627\u0642\u0641\u0632 \u0641\u0648\u0642\u0647 \u0639\u0646\u062f\u0645\u0627 \u064a\u0642\u062a\u0631\u0628 \u0645\u0646 \u0642\u062f\u0645\u064a\u0643.\n\u0627\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643 \u0648\u0643\u0631\u0631 \u0627\u0644\u0642\u0641\u0632\u0629 \u0628\u064a\u0646\u0645\u0627 \u064a\u0639\u0648\u062f \u0627\u0644\u062d\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0642\u0641\u0632 \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0623\u0648 \u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2612","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"cardio","classification_status":"needs_review","source_target":"cardiovascular system","secondary_muscles":["calves","quadriceps","hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2612-e1e76I2.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2612-e1e76I2.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"410a8023-1a5c-5c51-882e-3c53ebf7d8d1","source_id":"0514","name_en":"jump squat","name_ar":"\u0627\u0644\u0642\u0641\u0632 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621","match_names":["jump squat"],"muscle":"glutes","equipment":"bodyweight","aliases":["jump squat"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nLower your body into a squat position by bending your knees and pushing your hips back.\nJump explosively off the ground, extending your hips, knees, and ankles.\nWhile in mid-air, quickly bring your arms forward for balance.\nLand softly on the balls of your feet and immediately go into the next repetition.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u0642\u0641\u0632 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0643\u0627\u062d\u0644\u064a\u0646.\n\u0623\u062b\u0646\u0627\u0621 \u0648\u062c\u0648\u062f\u0643 \u0641\u064a \u0627\u0644\u0647\u0648\u0627\u0621\u060c \u0627\u0631\u0641\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0633\u0631\u0639\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646.\n\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0639\u0644\u0649 \u0643\u0631\u0627\u062a \u0642\u062f\u0645\u064a\u0643 \u0648\u0627\u0646\u062a\u0642\u0644 \u0639\u0644\u0649 \u0627\u0644\u0641\u0648\u0631 \u0625\u0644\u0649 \u0627\u0644\u062a\u0643\u0631\u0627\u0631 \u0627\u0644\u062a\u0627\u0644\u064a.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0514","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0514-LIlE5Tn.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0514-LIlE5Tn.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"bef35d16-1213-56a6-8beb-db4bce9ff52c","source_id":"0513","name_en":"jump squat v. 2","name_ar":"\u0627\u0644\u0642\u0641\u0632 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 v.2","match_names":["jump squat v. 2"],"muscle":"glutes","equipment":"bodyweight","aliases":["jump squat v. 2"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nLower your body into a squat position by bending your knees and pushing your hips back.\nJump explosively, extending your hips and knees fully.\nLand softly on the balls of your feet and immediately lower your body back into a squat position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u0642\u0641\u0632 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643 \u062b\u0645 \u0627\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0641\u0648\u0631\u064b\u0627 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0513","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0513-TDYiji6.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0513-TDYiji6.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2a844b35-bb7a-5f64-8b84-6ee80653ffcc","source_id":"0517","name_en":"kettlebell advanced windmill","name_ar":"\u0637\u0627\u062d\u0648\u0646\u0629 Kettlebell \u0627\u0644\u0645\u062a\u0642\u062f\u0645\u0629","match_names":["kettlebell advanced windmill"],"muscle":"core","equipment":"kettlebell","aliases":["kettlebell advanced windmill"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet wider than shoulder-width apart, toes pointing slightly outward.\nHold a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.\nRotate your left foot slightly to the right, and shift your weight onto your left leg.\nBend your left knee and hinge at the hip, lowering your torso towards the left side.\nKeep your right arm extended overhead and your eyes on the kettlebell.\nAs you lower your torso, allow your right leg to straighten and your right foot to pivot slightly.\nLower your torso until you feel a stretch in your left hamstring and your right arm is pointing towards the ground.\nPause for a moment, then engage your core and push through your left heel to return to the starting position.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0627\u0644\u0642\u062f\u0645 \u0646\u062d\u0648 \u0627\u0644\u062e\u0627\u0631\u062c \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062c\u0631\u0633 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0648\u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0642\u0644\u064a\u0644\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u064a\u0645\u064a\u0646\u060c \u0648\u0642\u0645 \u0628\u062a\u062d\u0648\u064a\u0644 \u0648\u0632\u0646\u0643 \u0639\u0644\u0649 \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u062b\u0628\u062a\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u060c \u0645\u0639 \u062e\u0641\u0636 \u0627\u0644\u062c\u0630\u0639 \u0646\u062d\u0648 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0623\u064a\u0633\u0631.\n\u0623\u0628\u0642\u0650 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0645\u0645\u062a\u062f\u0629 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643 \u0648\u0639\u064a\u0646\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0631\u0633.\n\u0623\u062b\u0646\u0627\u0621 \u062e\u0641\u0636 \u062c\u0630\u0639\u0643\u060c \u0627\u0633\u0645\u062d \u0644\u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0627\u0644\u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0648\u0644\u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0627\u0644\u062f\u0648\u0631\u0627\u0646 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0627\u062e\u0641\u0636 \u062c\u0630\u0639\u0643 \u062d\u062a\u0649 \u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u064a\u0634\u064a\u0631 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u062a\u0634\u063a\u064a\u0644 \u062c\u0630\u0639\u0643 \u0648\u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u0643 \u0627\u0644\u0623\u064a\u0633\u0631 \u0644\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0517","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0517-Kal9cQQ.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0517-Kal9cQQ.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5ca0c7ce-881a-5e05-82b5-c2f9b90aa245","source_id":"0518","name_en":"kettlebell alternating hang clean","name_ar":"Kettlebell \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0634\u0646\u0642 \u0646\u0638\u064a\u0641\u0629","match_names":["kettlebell alternating hang clean"],"muscle":"forearms","equipment":"kettlebell","aliases":["kettlebell alternating hang clean"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.\nBend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\nAllow the kettlebells to hang in front of your body with your arms fully extended.\nIn one fluid motion, explosively extend your hips, shrug your shoulders, and pull the kettlebells up towards your shoulders.\nAs the kettlebells reach shoulder height, rotate your wrists and catch the kettlebells in the rack position, with your palms facing inward and the kettlebells resting on the outside of your forearms.\nLower the kettlebells back down to the starting position and repeat the movement with the opposite arm.\nContinue alternating arms for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062c\u0631\u0633 \u0641\u064a \u0643\u0644 \u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0633\u0645\u062d \u0644\u0644\u0623\u062c\u0631\u0627\u0633 \u0628\u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0623\u0645\u0627\u0645 \u062c\u0633\u0645\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0641\u064a \u062d\u0631\u0643\u0629 \u0633\u0644\u0633\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0648\u0631\u0643\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0648\u0647\u0632 \u0643\u062a\u0641\u064a\u0643\u060c \u0648\u0627\u0633\u062d\u0628 \u0623\u062c\u0631\u0627\u0633 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u0644 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u0635\u0644 \u0643\u0631\u0627\u062a \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u060c \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0645\u0639\u0635\u0645\u064a\u0643 \u0648\u0627\u0645\u0633\u0643 \u0643\u064a\u062a\u0644 \u0628\u064a\u0644\u0632 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0631\u0641\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0644\u062f\u0627\u062e\u0644 \u0648\u062a\u0633\u062a\u0642\u0631 \u0643\u064a\u062a\u0644 \u0628\u064a\u0644\u0632 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0645\u0646 \u0633\u0627\u0639\u062f\u064a\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0627\u0644\u062d\u0631\u0643\u0629 \u0628\u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0645\u0639\u0627\u0643\u0633.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0518","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"forearms","secondary_muscles":["shoulders","traps","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0518-I4tibZG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0518-I4tibZG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"960b48ed-758b-5fbd-80d6-0b6ced815764","source_id":"0520","name_en":"kettlebell alternating press","name_ar":"\u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 Kettlebell","match_names":["kettlebell alternating press"],"muscle":"shoulders","equipment":"kettlebell","aliases":["kettlebell alternating press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.\nPress one kettlebell overhead, fully extending your arm.\nLower the kettlebell back to shoulder height.\nRepeat with the other arm.\nContinue alternating arms for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062f\u064a\u0629 \u0641\u064a \u0643\u0644 \u064a\u062f \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u062c\u0631\u0633 \u0648\u0627\u062d\u062f \u0645\u0646 \u0623\u0639\u0644\u0649 \u0631\u0623\u0633\u0643\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u062e\u0641\u0636 Kettlebell \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0520","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0520-5KLbZWx.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0520-5KLbZWx.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5a844705-3b54-5fba-869f-f26649525c9a","source_id":"0519","name_en":"kettlebell alternating press on floor","name_ar":"\u0627\u0636\u063a\u0637 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0639\u0644\u0649 Kettlebell \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636","match_names":["kettlebell alternating press on floor"],"muscle":"chest","equipment":"kettlebell","aliases":["kettlebell alternating press on floor"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Start by lying on your back on the floor with your knees bent and feet flat on the ground.\nHold a kettlebell in each hand, with your palms facing towards your feet and your arms extended straight up towards the ceiling.\nLower one kettlebell down towards your shoulder while keeping the other kettlebell extended straight up.\nPress the lowered kettlebell back up to the starting position while simultaneously lowering the other kettlebell down towards your shoulder.\nContinue alternating the press motion with each kettlebell for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0646\u062d\u0648 \u0642\u062f\u0645\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u062a\u064a\u0646 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0646\u062d\u0648 \u0627\u0644\u0633\u0642\u0641.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0623\u062d\u062f \u0627\u0644\u062c\u0631\u0633 \u0644\u0623\u0633\u0641\u0644 \u0628\u0627\u062a\u062c\u0627\u0647 \u0643\u062a\u0641\u0643 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u062c\u0631\u0633 \u0627\u0644\u0622\u062e\u0631 \u0645\u0645\u062a\u062f\u064b\u0627 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u062c\u0631\u0633 \u0627\u0644\u0645\u0646\u062e\u0641\u0636 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0628\u064a\u0646\u0645\u0627 \u062a\u0642\u0648\u0645 \u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a \u0628\u062e\u0641\u0636 \u0627\u0644\u062c\u0631\u0633 \u0627\u0644\u0622\u062e\u0631 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u062d\u0631\u0643\u0629 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0643\u0644 \u062c\u0631\u0633 \u0644\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0519","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["shoulders","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0519-7w6i0vE.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0519-7w6i0vE.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"592c1dc8-0ef1-5f1a-8381-1fc38063852f","source_id":"0521","name_en":"kettlebell alternating renegade row","name_ar":"Kettlebell \u0627\u0644\u0635\u0641 \u0627\u0644\u0645\u062a\u0645\u0631\u062f \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628","match_names":["kettlebell alternating renegade row"],"muscle":"back","equipment":"kettlebell","aliases":["kettlebell alternating renegade row"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Start in a high plank position with your hands gripping the kettlebells and your feet hip-width apart.\nEngage your core and keep your body in a straight line from head to heels.\nPull one kettlebell up towards your chest, keeping your elbow close to your body.\nLower the kettlebell back down to the starting position and repeat with the other arm.\nContinue alternating arms for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0625\u0645\u0633\u0627\u0643 \u064a\u062f\u064a\u0643 \u0628\u0623\u062c\u0631\u0627\u0633 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u064a\u0644 \u0648\u0642\u062f\u0645\u064a\u0643 \u0628\u0639\u0631\u0636 \u0645\u0641\u0635\u0644 \u0627\u0644\u0648\u0631\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062c\u0633\u0645\u0643 \u0641\u064a \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628.\n\u0627\u0633\u062d\u0628 \u0643\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0627\u062a\u062c\u0627\u0647 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u0643 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062c\u0631\u0633 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u062b\u0645 \u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0521","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["core","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0521-b9kqlBy.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0521-b9kqlBy.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"0c7cc7cb-a3d3-54f7-8cc6-882ad6e985d9","source_id":"0522","name_en":"kettlebell alternating row","name_ar":"\u0627\u0644\u0635\u0641 \u0627\u0644\u0645\u062a\u0646\u0627\u0648\u0628 Kettlebell","match_names":["kettlebell alternating row"],"muscle":"back","equipment":"kettlebell","aliases":["kettlebell alternating row"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, knees slightly bent, and hold a kettlebell in each hand with your palms facing your body.\nBend forward at the hips, keeping your back straight and your core engaged.\nPull one kettlebell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.\nLower the kettlebell back down to the starting position and repeat with the other arm.\nContinue alternating arms for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u062b\u0646\u064a \u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0642\u0644\u064a\u0644\u064b\u0627\u060c \u0648\u0627\u062d\u0645\u0644 \u0627\u0644\u062c\u0631\u0633 \u0641\u064a \u0643\u0644 \u064a\u062f \u0645\u0639 \u0648\u0636\u0639 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0633\u0645\u0643.\n\u0627\u0646\u062d\u0646\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062c\u0630\u0628 \u062c\u0630\u0639\u0643.\n\u0627\u0633\u062d\u0628 \u062c\u0631\u0633\u064b\u0627 \u0648\u0627\u062d\u062f\u064b\u0627 \u0644\u0644\u0623\u0639\u0644\u0649 \u0628\u0627\u062a\u062c\u0627\u0647 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0648\u0639\u0643 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u062c\u0633\u0645\u0643 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u0623\u0646\u0632\u0644 \u0627\u0644\u062c\u0631\u0633 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629\u060c \u062b\u0645 \u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u0630\u0631\u0627\u0639 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0630\u0631\u0627\u0639\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0522","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0522-Ca76jUE.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0522-Ca76jUE.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"99c27033-b8e4-5a01-86da-3d06306b4335","source_id":"0523","name_en":"kettlebell arnold press","name_ar":"\u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0643\u064a\u062a\u0644\u0628\u0644 \u0623\u0631\u0646\u0648\u0644\u062f","match_names":["kettlebell arnold press"],"muscle":"shoulders","equipment":"kettlebell","aliases":["kettlebell arnold press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height with your palms facing towards you.\nEngage your core and press the kettlebells overhead, rotating your palms to face forward as you extend your arms.\nPause at the top of the movement, then slowly lower the kettlebells back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u0644 \u0641\u064a \u0643\u0644 \u064a\u062f \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0646\u062d\u0648\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0643\u064a\u062a\u0644 \u0628\u064a\u0644\u0632 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0631\u0627\u062d\u062a\u064a \u064a\u062f\u064a\u0643 \u0644\u0645\u0648\u0627\u062c\u0647\u0629 \u0627\u0644\u0623\u0645\u0627\u0645 \u0623\u062b\u0646\u0627\u0621 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0523","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","upper back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0523-UM8mgyG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0523-UM8mgyG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"413cfa40-c111-5ead-8389-b4f769ac303b","source_id":"0524","name_en":"kettlebell bent press","name_ar":"\u0627\u0644\u0635\u062d\u0627\u0641\u0629 \u0639\u0627\u0632\u0645\u0629 Kettlebell","match_names":["kettlebell bent press"],"muscle":"core","equipment":"kettlebell","aliases":["kettlebell bent press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a kettlebell in your right hand.\nBend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.\nRotate your torso to the left, shifting your weight onto your left foot.\nBend your left knee and lower your torso towards the ground, keeping your right arm extended overhead.\nAs you lower, keep your eyes on the kettlebell and your chest lifted.\nOnce your left hand touches the ground, push through your left foot and straighten your left leg, driving your hips forward.\nAs you drive your hips forward, use your core and right arm to press the kettlebell back up to the starting position.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062f\u064a\u0629 \u0641\u064a \u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u0644 \u0628\u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0623\u064a\u0645\u0646\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u0643 \u0645\u063a\u0644\u0642\u064b\u0627.\n\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u062c\u0630\u0639\u0643 \u0625\u0644\u0649 \u0627\u0644\u064a\u0633\u0627\u0631\u060c \u0645\u0639 \u0646\u0642\u0644 \u0648\u0632\u0646\u0643 \u0625\u0644\u0649 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u062e\u0641\u0636 \u062c\u0630\u0639\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0645\u0645\u062a\u062f\u0629 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643.\n\u0628\u064a\u0646\u0645\u0627 \u062a\u0646\u0632\u0644\u060c \u0623\u0628\u0642 \u0639\u064a\u0646\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0631\u0633 \u0648\u0631\u0641\u0639 \u0635\u062f\u0631\u0643.\n\u0628\u0645\u062c\u0631\u062f \u0623\u0646 \u062a\u0644\u0645\u0633 \u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0627\u0644\u0623\u0631\u0636\u060c \u0627\u062f\u0641\u0639 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0648\u0627\u0641\u0631\u062f \u0633\u0627\u0642\u0643 \u0627\u0644\u064a\u0633\u0631\u0649\u060c \u0648\u0627\u062f\u0641\u0639 \u0648\u0631\u0643\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0623\u062b\u0646\u0627\u0621 \u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0627\u0633\u062a\u062e\u062f\u0645 \u062c\u0630\u0639\u0643 \u0648\u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0623\u064a\u0645\u0646 \u0644\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0524","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["shoulders","triceps","obliques"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0524-kjE55n5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0524-kjE55n5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b3034ece-58e3-585e-8de1-f109e73edb75","source_id":"0525","name_en":"kettlebell bottoms up clean from the hang position","name_ar":"\u0642\u064a\u0639\u0627\u0646 \u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0646\u0638\u064a\u0641\u0629 \u0645\u0646 \u0648\u0636\u0639 \u0627\u0644\u062a\u0639\u0644\u064a\u0642","match_names":["kettlebell bottoms up clean from the hang position"],"muscle":"biceps","equipment":"kettlebell","aliases":["kettlebell bottoms up clean from the hang position"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a kettlebell in one hand with an overhand grip.\nBend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\nAllow the kettlebell to hang down between your legs, with your arm fully extended.\nIn one fluid motion, explosively extend your hips and knees while pulling the kettlebell up towards your shoulder.\nAs the kettlebell reaches shoulder height, rotate your wrist so that the bottom of the kettlebell is facing up.\nCatch the kettlebell at shoulder height with your elbow bent and your palm facing up.\nLower the kettlebell back down to the starting position by reversing the movement.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062f\u064a\u0629 \u0641\u064a \u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0633\u0645\u062d \u0644\u0644\u062c\u0631\u0633 \u0628\u0627\u0644\u062a\u062f\u0644\u064a \u0628\u064a\u0646 \u0633\u0627\u0642\u064a\u0643\u060c \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0641\u064a \u062d\u0631\u0643\u0629 \u0633\u0644\u0633\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0623\u062b\u0646\u0627\u0621 \u0633\u062d\u0628 \u0627\u0644\u062c\u0631\u0633 \u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643.\n\u0639\u0646\u062f\u0645\u0627 \u064a\u0635\u0644 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u060c \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0645\u0639\u0635\u0645\u0643 \u0628\u062d\u064a\u062b \u064a\u0643\u0648\u0646 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0645\u062a\u062c\u0647\u064b\u0627 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062c\u0631\u0633 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641 \u0645\u0639 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u0643 \u0648\u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u062c\u0631\u0633 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0639\u0643\u0633 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0525","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0525-4KJEpzb.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0525-4KJEpzb.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"1ac4dd7d-f252-55e7-872b-18018a206dd9","source_id":"0526","name_en":"kettlebell double alternating hang clean","name_ar":"Kettlebell \u0645\u0632\u062f\u0648\u062c \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0634\u0646\u0642 \u0646\u0638\u064a\u0641\u0629","match_names":["kettlebell double alternating hang clean"],"muscle":"biceps","equipment":"kettlebell","aliases":["kettlebell double alternating hang clean"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand with an overhand grip.\nBend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.\nAllow the kettlebells to hang straight down in front of your body.\nIn one fluid motion, explosively extend your hips and knees while shrugging your shoulders.\nAs the kettlebells rise, pull them up towards your shoulders, keeping your elbows high and out to the sides.\nCatch the kettlebells at shoulder height, with your palms facing inward and your elbows pointing forward.\nLower the kettlebells back down to the starting position and repeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062c\u0631\u0633 \u0641\u064a \u0643\u0644 \u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0633\u0645\u062d \u0644\u0644\u0623\u062c\u0631\u0627\u0633 \u0623\u0646 \u062a\u062a\u062f\u0644\u0649 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645 \u062c\u0633\u0645\u0643.\n\u0641\u064a \u062d\u0631\u0643\u0629 \u0648\u0627\u062d\u062f\u0629 \u0633\u0644\u0633\u0629\u060c \u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631 \u0628\u064a\u0646\u0645\u0627 \u062a\u0647\u0632 \u0643\u062a\u0641\u064a\u0643.\n\u0623\u062b\u0646\u0627\u0621 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644\u060c \u0627\u0633\u062d\u0628\u0647\u0627 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0645\u0631\u062a\u0641\u0639\u064a\u0646 \u0648\u0645\u062a\u062c\u0647\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u0644\u0632 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u062f\u0627\u062e\u0644 \u0648\u0645\u0631\u0641\u0642\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0526","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0526-a4F9Oyc.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0526-a4F9Oyc.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"34d50528-3368-5c05-8749-ceefc583c479","source_id":"0527","name_en":"kettlebell double jerk","name_ar":"\u0631\u0639\u0634\u0629 \u0643\u064a\u062a\u0644\u0628\u064a\u0644 \u0645\u0632\u062f\u0648\u062c\u0629","match_names":["kettlebell double jerk"],"muscle":"shoulders","equipment":"kettlebell","aliases":["kettlebell double jerk"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.\nBend your knees slightly and engage your core.\nPress the kettlebells overhead, fully extending your arms.\nBend your knees and quickly drop into a partial squat.\nExplosively extend your hips and knees, driving the kettlebells overhead.\nLock out your arms and catch the kettlebells overhead with your knees slightly bent.\nStand up straight and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062f\u064a\u0629 \u0641\u064a \u0643\u0644 \u064a\u062f \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627 \u0648\u0627\u0634\u0631\u0643 \u0642\u0644\u0628\u0643.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 Kettlebells \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u062b\u0645 \u0627\u0646\u0632\u0644 \u0628\u0633\u0631\u0639\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0627\u0644\u062c\u0632\u0626\u064a\u0629.\n\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0645\u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u062f\u0641\u0639 \u0623\u062c\u0631\u0627\u0633 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0642\u0641\u0644 \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0627\u0645\u0633\u0643 \u0628\u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062f\u064a\u0629 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643 \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0627\u0644\u0648\u0642\u0648\u0641 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0527","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0527-tznL2Ad.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0527-tznL2Ad.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"80cfbf1e-5dd0-5a92-8b39-0d4f0b40f6e8","source_id":"0528","name_en":"kettlebell double push press","name_ar":"\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0636\u063a\u0637 \u0645\u0632\u062f\u0648\u062c \u0645\u0646 Kettlebell","match_names":["kettlebell double push press"],"muscle":"shoulders","equipment":"kettlebell","aliases":["kettlebell double push press"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Start by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height.\nBend your knees slightly and engage your core.\nInitiate the movement by explosively extending your hips, knees, and ankles, driving the kettlebells overhead.\nAs the kettlebells reach the top, press them fully overhead, locking out your arms.\nLower the kettlebells back to the starting position by bending your elbows and bringing them back down to shoulder height.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0648\u0642\u0648\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062f\u064a\u0629 \u0641\u064a \u0643\u0644 \u064a\u062f \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627 \u0648\u0627\u0634\u0631\u0643 \u0642\u0644\u0628\u0643.\n\u0627\u0628\u062f\u0623 \u0627\u0644\u062d\u0631\u0643\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0643\u0627\u062d\u0644\u064a\u0646 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0645\u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u062f\u0641\u0639 \u0623\u062c\u0631\u0627\u0633 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u0635\u0644 \u0643\u0631\u0627\u062a \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u0627\u0636\u063a\u0637 \u0639\u0644\u064a\u0647\u0627 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0645\u0639 \u0642\u0641\u0644 \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u0625\u0639\u0627\u062f\u062a\u0647\u0645\u0627 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0528","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["triceps","core"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0528-I4KkPdl.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0528-I4KkPdl.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"be1cfbc8-e115-5eb6-846f-59b1ea5a2a53","source_id":"0529","name_en":"kettlebell double snatch","name_ar":"\u062e\u0637\u0641 \u0645\u0632\u062f\u0648\u062c Kettlebell","match_names":["kettlebell double snatch"],"muscle":"shoulders","equipment":"kettlebell","aliases":["kettlebell double snatch"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a kettlebell in each hand at arm''s length in front of your thighs.\nBend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.\nIn one explosive motion, extend your hips, knees, and ankles, and simultaneously pull the kettlebells up towards your shoulders.\nAs the kettlebells reach shoulder level, rotate your wrists and punch the kettlebells overhead, fully extending your arms.\nLower the kettlebells back down to the starting position and repeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u0625\u0645\u0633\u0627\u0643 \u0628\u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u062d\u062f\u064a\u062f\u064a\u0629 \u0641\u064a \u0643\u0644 \u064a\u062f \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0630\u0631\u0627\u0639 \u0623\u0645\u0627\u0645 \u0641\u062e\u0630\u064a\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062b\u0628\u062a\u0647\u0645\u0627 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0633\u0637\u062d\u064b\u0627 \u0648\u0635\u062f\u0631\u0643 \u0644\u0623\u0639\u0644\u0649.\n\u0641\u064a \u062d\u0631\u0643\u0629 \u0648\u0627\u062d\u062f\u0629 \u0645\u062a\u0641\u062c\u0631\u0629\u060c \u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0643\u0627\u062d\u0644\u064a\u0646\u060c \u0648\u0641\u064a \u0646\u0641\u0633 \u0627\u0644\u0648\u0642\u062a \u0627\u0633\u062d\u0628 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644\u0632 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643.\n\u0639\u0646\u062f\u0645\u0627 \u062a\u0635\u0644 \u0643\u0631\u0627\u062a \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0643\u062a\u0641\u060c \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0645\u0639\u0635\u0645\u064a\u0643 \u0648\u0644\u0643\u0645\u0647\u0627 \u0641\u0648\u0642 \u0631\u0623\u0633\u0643\u060c \u0645\u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.","text_sourc