23\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0645\u0627 \u064a\u0633\u0645\u062d \u0644\u0647 \u0628\u0627\u0644\u062a\u0623\u0631\u062c\u062d \u0628\u064a\u0646 \u0633\u0627\u0642\u064a\u0643.\n\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0628\u0633\u0631\u0639\u0629\u060c \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u0632\u062e\u0645 \u0644\u062a\u0623\u0631\u062c\u062d \u0627\u0644\u062c\u0631\u0633 \u062d\u062a\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0639\u0646\u062f\u0645\u0627 \u064a\u0635\u0644 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0625\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641\u060c \u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0645\u0639\u0635\u0645\u064a\u0643 \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u062c\u0631\u0633 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0631\u0641\u060c \u0645\u0639 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u0643 \u0644\u0644\u062f\u0627\u062e\u0644 \u0648\u0648\u0636\u0639 \u0627\u0644\u062c\u0631\u0633 \u0639\u0644\u0649 \u0633\u0627\u0639\u062f\u0643.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0643\u064a\u062a\u0644\u0628\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0628\u064a\u0646 \u0633\u0627\u0642\u064a\u0643\u060c \u062b\u0645 \u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u064